"""FS: LayerSkip self-speculation with a finite-state draft length (DEL's FS baseline).

Paper: DEL (Entezari Zarch et al., COLM 2025, arXiv:2504.05598), baseline FS(E-gamma):
"initializes the speculation length to gamma, then adjusts it using a
finite-state controller: it increases by 1 if all draft tokens are accepted in
the previous round, and decreases by 1 if any are rejected (Liu et al., 2025)".
Reference code: hoenza/DEL@6369bf7cc0304e1aa474af65e7a0675f2663c31c
self_speculation/FSM_speculation_generator.py
* draft loop (:139-157): exactly ``num_speculations`` early-exit tokens through
  layers [:exit_layer], stopping only at EOS;
* update (:96-99): ``if number_of_matches == num_speculations: += 1 else -= 1``
  (no bounds; at 0 the round drafts nothing and the next goes back to 1);
* benchmark.py:203-204 resets the length to its initial value for every prompt.
Hyperparameters: E = 3, initial gamma = 6 (DEL Table 1, FS(E3-gamma6), both
LLaMA-3.2-1B and LLaMA-3-8B).
Harness convention shared by every arm: the prompt's prefill pass emits the
first token (the reference implementation drafts it); no other difference.
Verdict: faithful, no deviations.
"""
_FILE = "layerskip-ee-lab/mlsee/draft_policy.py"

_CONTENT = '''EXIT_LAYER = 3
INIT_GAMMA = 6


def calibrate(cal, n_layers, seed, simulate):
    return {}


def begin(prompt, state):
    state["gamma"] = INIT_GAMMA


def plan(state, ops):
    return {"exit": EXIT_LAYER, "max_draft": max(0, state["gamma"])}


def step(feat, state):
    return True


def tree(steps, state):
    raise NotImplementedError


def observe(result, state):
    if result["accepted"] == state["gamma"]:
        state["gamma"] += 1
    else:
        state["gamma"] -= 1
'''

OPS = [{"op": "replace", "file": _FILE, "start_line": 79, "end_line": 112, "content": _CONTENT}]

"""Draft & Verify (Zhang et al., ACL 2024, arXiv:2309.08168) on LayerSkip: DEL's DV(E) baseline.

Adaptive draft-exiting: drafting stops once the draft token's probability falls
below a threshold that is moved to hold a target acceptance rate.
Reference code (the DV(E) baseline DEL compares against, on these LayerSkip
checkpoints): hoenza/DEL@6369bf7cc0304e1aa474af65e7a0675f2663c31c
self_speculation/DV_speculation_generator.py
* constants (:33-39): beta_1 = 0.5, beta_2 = 0.9, alpha (target acceptance) =
  0.8, initial threshold 0.6, epsilon = 0.01;
* draft loop (:157-177): up to d_max = 18 tokens through layers [:exit_layer];
  stop at EOS, or after a token whose probability (softmax of the draft head at
  its argmax) is below the threshold (that token is still drafted);
* update after every round (:92-101): accr = matches / drafted so far in this
  prompt; AR = accr on first use, else beta_1 AR + (1 - beta_1) accr;
  threshold' = threshold + eps if AR < alpha else threshold - eps;
  threshold = beta_2 threshold + (1 - beta_2) threshold';
* the strategy object is built once per benchmark (benchmark.py:177-186), so AR
  and the threshold carry over from prompt to prompt; the counts are per prompt.
The same rule is dilab-zju/self-speculative-decoding@688db8b decoding.py
(adaptive draft-exiting, same constants).  E = 3 (DEL Table 1, DV(E3), both
models).
Harness convention shared by every arm: the prompt's prefill pass emits the
first token.  Probabilities come from float32 logits (the reference takes the
softmax of the bf16 head output).  Verdict: faithful, no deviations.
"""
_FILE = "layerskip-ee-lab/mlsee/draft_policy.py"

_CONTENT = '''EXIT_LAYER = 3
D_MAX = 18
BETA_1, BETA_2, ALPHA, EPS = 0.5, 0.9, 0.8, 0.01


def calibrate(cal, n_layers, seed, simulate):
    return {"AR": 0.0, "cs": 0.6}


def begin(prompt, state):
    state["matches"] = 0
    state["drafted"] = 0


def plan(state, ops):
    return {"exit": EXIT_LAYER, "max_draft": D_MAX, "feedback": True}


def step(feat, state):
    p = float(np.exp(np.float64(feat["top_val"][0, 0]) - np.float64(feat["lse"][0])))
    return not (p < state["cs"])


def tree(steps, state):
    raise NotImplementedError


def observe(result, state):
    state["matches"] += result["accepted"]
    state["drafted"] += result["n_draft"]
    if state["drafted"] == 0:
        return
    accr = state["matches"] / state["drafted"]
    if state["AR"] == 0:
        state["AR"] = accr
    else:
        state["AR"] = BETA_1 * state["AR"] + (1 - BETA_1) * accr
    new = state["cs"] + EPS if state["AR"] < ALPHA else state["cs"] - EPS
    state["cs"] = BETA_2 * state["cs"] + (1 - BETA_2) * new
'''

OPS = [{"op": "replace", "file": _FILE, "start_line": 79, "end_line": 112, "content": _CONTENT}]

"""Null: a random exit layer every round, fixed draft length.

The draft depth reads nothing: E is drawn uniformly from 1..L-1 per round by a
hash of (seed, prompt, round), 6 draft tokens per round (the starter's length).
"""
_FILE = "layerskip-ee-lab/mlsee/draft_policy.py"

_CONTENT = '''GAMMA = 6


def calibrate(cal, n_layers, seed, simulate):
    return {"L": int(n_layers), "seed": int(seed)}


def begin(prompt, state):
    state["seq"] = int(prompt["seq"])
    state["round"] = 0


def plan(state, ops):
    rs = np.random.RandomState((state["seed"] * 1000003 + state["seq"] * 7919 + state["round"]) % (2 ** 31))
    state["round"] += 1
    return {"exit": int(rs.randint(1, state["L"])), "max_draft": GAMMA}


def step(feat, state):
    return True


def tree(steps, state):
    raise NotImplementedError


def observe(result, state):
    pass
'''

OPS = [{"op": "replace", "file": _FILE, "start_line": 79, "end_line": 112, "content": _CONTENT}]
